-- Run in Supabase SQL Editor. RLS enabled on every user-generated table.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text,engineering_branch text,created_at timestamptz not null default now());
create table if not exists public.subjects (id bigint generated always as identity primary key,name text not null unique);
create table if not exists public.topics (id bigint generated always as identity primary key,subject_id bigint not null references public.subjects(id),name text not null);
create table if not exists public.tutorials (id bigint generated always as identity primary key,topic_id bigint not null references public.topics(id),title text not null,content text not null default '',published boolean not null default false);
create table if not exists public.community_posts (id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 1 and 140),body text not null check(length(body) between 1 and 20000),anonymous boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.post_comments (id uuid primary key default gen_random_uuid(),post_id uuid not null references public.community_posts(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,body text not null check(length(body) between 1 and 10000),verified boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.post_votes (post_id uuid not null references public.community_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,value smallint not null check(value in(-1,1)),primary key(post_id,user_id));
create table if not exists public.exams (id bigint generated always as identity primary key,name text not null,description text,application_deadline timestamptz,exam_date timestamptz,official_url text,stage text not null default 'notification',published boolean not null default false);
create table if not exists public.exam_reminders (user_id uuid not null references auth.users(id) on delete cascade,exam_id bigint not null references public.exams(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,exam_id));
create table if not exists public.student_progress (user_id uuid not null references auth.users(id) on delete cascade,topic_id bigint not null references public.topics(id),completion_percent integer not null default 0 check(completion_percent between 0 and 100),updated_at timestamptz not null default now(),primary key(user_id,topic_id));
create table if not exists public.daily_questions (id bigint generated always as identity primary key,question_date date not null unique,prompt text not null,correct_answer numeric not null,explanation text not null);
create table if not exists public.student_answers (id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,question_id bigint not null references public.daily_questions(id),submitted_answer numeric not null,is_correct boolean not null default false,created_at timestamptz not null default now(),unique(user_id,question_id));
-- Do not expose correct_answer to the client; use a secure server-side grading function in a later iteration.
alter table public.profiles enable row level security;
alter table public.subjects enable row level security;
alter table public.topics enable row level security;
alter table public.tutorials enable row level security;
alter table public.community_posts enable row level security;
alter table public.post_comments enable row level security;
alter table public.post_votes enable row level security;
alter table public.exams enable row level security;
alter table public.exam_reminders enable row level security;
alter table public.student_progress enable row level security;
alter table public.daily_questions enable row level security;
alter table public.student_answers enable row level security;
create policy "Own profile" on public.profiles for select to authenticated using(id=auth.uid());
create policy "Insert own profile" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "Update own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "Public subjects" on public.subjects for select to anon,authenticated using(true);
create policy "Public topics" on public.topics for select to anon,authenticated using(true);
create policy "Published tutorials" on public.tutorials for select to anon,authenticated using(published);
create policy "Read posts" on public.community_posts for select to anon,authenticated using(true);
create policy "Create own posts" on public.community_posts for insert to authenticated with check(author_id=auth.uid());
create policy "Delete own posts" on public.community_posts for delete to authenticated using(author_id=auth.uid());
create policy "Read comments" on public.post_comments for select to anon,authenticated using(true);
create policy "Create own unverified comments" on public.post_comments for insert to authenticated with check(author_id=auth.uid() and verified=false);
create policy "Read votes" on public.post_votes for select to anon,authenticated using(true);
create policy "Vote as self" on public.post_votes for insert to authenticated with check(user_id=auth.uid());
create policy "Update own vote" on public.post_votes for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "Delete own vote" on public.post_votes for delete to authenticated using(user_id=auth.uid());
create policy "Published exams" on public.exams for select to anon,authenticated using(published);
create policy "Own reminders read" on public.exam_reminders for select to authenticated using(user_id=auth.uid());
create policy "Own reminders insert" on public.exam_reminders for insert to authenticated with check(user_id=auth.uid());
create policy "Own reminders delete" on public.exam_reminders for delete to authenticated using(user_id=auth.uid());
create policy "Own progress read" on public.student_progress for select to authenticated using(user_id=auth.uid());
create policy "Own progress insert" on public.student_progress for insert to authenticated with check(user_id=auth.uid());
create policy "Own progress update" on public.student_progress for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
-- No client policies on daily_questions/student_answers until server-side answer validation is implemented.
insert into public.subjects(name) values('Electrical Engineering'),('Computer Science'),('Mechanical Engineering'),('Civil Engineering') on conflict(name) do nothing;
